// Product-aware chunker: variant grain + metadata (plain JS)
function chunkProduct(product) {
  const chunks = [];
  for (const v of product.variants) {
    chunks.push({
      id: `${product.sku}-${v.sku}`,
      text: `${product.name} (${v.size}, ${v.color}): $${v.price}. ${product.blurb}`,
      meta: { sku: v.sku, parentSku: product.sku, category: product.category, price: v.price, version: product.version, updated: product.updated },
    });
  }
  chunks.push({
    id: `${product.sku}-policy`,
    text: `Returns for ${product.name}: ${product.returns}. Warranty: ${product.warranty}.`,
    meta: { sku: product.sku, category: product.category, kind: "policy", version: product.version, updated: product.updated },
  });
  return chunks;
}
// Grain = question grain; metadata = everything filters/citations/freshness need.

